window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-21a1446b56b1fdf2"]={"versions": [{"id": "FIG-21a1446b56b1fdf2", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Komponentendiagramm (VFB-/Architekturansicht). Das Diagramm visualisiert die Port-basierte Interaktion zwischen einer Software-Komponente (<code>SW-C</code>) und dem Basissoftware-Modul Communication Manager (<code>Com. Manager</code>) im Kontext der AUTOSAR Classic Platform. Es stellt die Modellierung von Modusanforderungen und Modusrückmeldungen über AUTOSAR-Ports und Schnittstellenverbindungen (Assembly-Konnektoren) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>SW-C (Software-Component)</strong>: Anwendungs- oder Dienstkomponente mit zwei R-Ports (Required Ports):\n<ul class=\"fig-list\"><li><code>require ComM_RequestMode</code>: Anforderungsport zur Signalisierung des gewünschten Kommunikationsmodus.\n</li><li><code>require ComM_CurrentMode</code>: Modusleseport zum Empfang des aktuellen Kommunikationsstatus.\n</li></ul>\n</li><li><strong>Com. Manager (Communication Manager Module)</strong>: BSW-Servicekomponente mit mehreren P-Ports (Provided Ports):\n<ul class=\"fig-list\"><li>Port <code>UR000</code> (<code>provide ComM_RequestMode</code>): Schnittstelle zur Entgegennahme von Modusanforderungen (User Request Port 000).\n</li><li>Port <code>UM000</code> (<code>provide ComM_CurrentMode</code>): Schnittstelle zur Bereitstellung des aktuellen Modus (User Mode Notification Port 000).\n</li><li>Weitere, durch vertikale Auslassungspunkte (<code>. . .</code> / <code>...</code>) angedeutete Port-Paare bzw. Ports für weitere Benutzer/Instanzen (UR/UM-Kanäle), darunter drei weitere P-Ports für Modusanforderungen (Lollipop-Notation) und zwei für Modusmeldungen bzw. alternative Schnittstellen.\n</li></ul>\n</li><li><strong>Verbindungen</strong>: Gestrichelte Konnektorlinien verbinden den R-Port <code>ComM_RequestMode</code> der SW-C mit dem P-Port <code>UR000</code> sowie den R-Port <code>ComM_CurrentMode</code> der SW-C mit dem P-Port <code>UM000</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die SW-C fordert über die Schnittstelle <code>ComM_RequestMode</code> am Port <code>UR000</code> des Communication Managers eine Zustandsänderung bzw. einen Kommunikationsmodus an.\n</li><li>Der Communication Manager verarbeitet die Anforderung intern im Rahmen seines Zustandsmanagements.\n</li><li>Der Communication Manager stellt den jeweils aktuellen Zustand/Modus über die Schnittstelle <code>ComM_CurrentMode</code> (Port <code>UM000</code>) bereit, welche von der SW-C über ihren korrespondierenden R-Port abgefragt bzw. empfangen wird.\n</li><li>Die multiplen Ports am Com. Manager zeigen, dass derselbe Mechanismus für mehrere unabhängige Benutzer/SW-Cs parallel über dedizierte Port-Instanzen (<code>URxxx</code> / <code>UMxxx</code>) skaliert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Definitionen &amp; Schnittstellentypen</strong>: Modusanforderungen und Statusabfragen erfolgen über standardisierte AUTOSAR-Client-Server- oder Mode-Switch-Schnittstellen (Sender-Receiver bzw. Mode Declaration Groups).\n</li><li><strong>Benutzerzuordnung (ComMUser)</strong>: Jeder kommunikationsbedürftige Nutzer (<code>SW-C</code>) muss im Systementwurf einem eindeutigen <code>ComMUser</code> zugeordnet werden, für den der ComM entsprechende Port-Paare (<code>UR...</code> / <code>UM...</code>) generiert.\n</li><li><strong>Entwickler-Hinweis</strong>: Die SW-C steuert Kommunikationskanäle nicht direkt an den Bus-Treibern, sondern abstrahiert über den Communication Manager. Vor der Übertragung von Nutzdaten muss der benötigte Modus aktiv angefordert und der bestätigte Status über <code>ComM_CurrentMode</code> abgewartet bzw. überwacht werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0f7da0b9b6fec343", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Komponentendiagramm (VFB-/Architekturansicht). Das Diagramm visualisiert die Port-basierte Interaktion zwischen einer Software-Komponente (<code>SW-C</code>) und dem Basissoftware-Modul Communication Manager (<code>Com. Manager</code>) im Kontext der AUTOSAR Classic Platform. Es stellt die Modellierung von Modusanforderungen und Modusrückmeldungen über AUTOSAR-Ports und Schnittstellenverbindungen (Assembly-Konnektoren) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>SW-C (Software-Component)</strong>: Anwendungs- oder Dienstkomponente mit zwei R-Ports (Required Ports):\n<ul class=\"fig-list\"><li><code>require ComM_RequestMode</code>: Anforderungsport zur Signalisierung des gewünschten Kommunikationsmodus.\n</li><li><code>require ComM_CurrentMode</code>: Modusleseport zum Empfang des aktuellen Kommunikationsstatus.\n</li></ul>\n</li><li><strong>Com. Manager (Communication Manager Module)</strong>: BSW-Servicekomponente mit mehreren P-Ports (Provided Ports):\n<ul class=\"fig-list\"><li>Port <code>UR000</code> (<code>provide ComM_RequestMode</code>): Schnittstelle zur Entgegennahme von Modusanforderungen (User Request Port 000).\n</li><li>Port <code>UM000</code> (<code>provide ComM_CurrentMode</code>): Schnittstelle zur Bereitstellung des aktuellen Modus (User Mode Notification Port 000).\n</li><li>Weitere, durch vertikale Auslassungspunkte (<code>. . .</code> / <code>...</code>) angedeutete Port-Paare bzw. Ports für weitere Benutzer/Instanzen (UR/UM-Kanäle), darunter drei weitere P-Ports für Modusanforderungen (Lollipop-Notation) und zwei für Modusmeldungen bzw. alternative Schnittstellen.\n</li></ul>\n</li><li><strong>Verbindungen</strong>: Gestrichelte Konnektorlinien verbinden den R-Port <code>ComM_RequestMode</code> der SW-C mit dem P-Port <code>UR000</code> sowie den R-Port <code>ComM_CurrentMode</code> der SW-C mit dem P-Port <code>UM000</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die SW-C fordert über die Schnittstelle <code>ComM_RequestMode</code> am Port <code>UR000</code> des Communication Managers eine Zustandsänderung bzw. einen Kommunikationsmodus an.\n</li><li>Der Communication Manager verarbeitet die Anforderung intern im Rahmen seines Zustandsmanagements.\n</li><li>Der Communication Manager stellt den jeweils aktuellen Zustand/Modus über die Schnittstelle <code>ComM_CurrentMode</code> (Port <code>UM000</code>) bereit, welche von der SW-C über ihren korrespondierenden R-Port abgefragt bzw. empfangen wird.\n</li><li>Die multiplen Ports am Com. Manager zeigen, dass derselbe Mechanismus für mehrere unabhängige Benutzer/SW-Cs parallel über dedizierte Port-Instanzen (<code>URxxx</code> / <code>UMxxx</code>) skaliert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Definitionen &amp; Schnittstellentypen</strong>: Modusanforderungen und Statusabfragen erfolgen über standardisierte AUTOSAR-Client-Server- oder Mode-Switch-Schnittstellen (Sender-Receiver bzw. Mode Declaration Groups).\n</li><li><strong>Benutzerzuordnung (ComMUser)</strong>: Jeder kommunikationsbedürftige Nutzer (<code>SW-C</code>) muss im Systementwurf einem eindeutigen <code>ComMUser</code> zugeordnet werden, für den der ComM entsprechende Port-Paare (<code>UR...</code> / <code>UM...</code>) generiert.\n</li><li><strong>Entwickler-Hinweis</strong>: Die SW-C steuert Kommunikationskanäle nicht direkt an den Bus-Treibern, sondern abstrahiert über den Communication Manager. Vor der Übertragung von Nutzdaten muss der benötigte Modus aktiv angefordert und der bestätigte Status über <code>ComM_CurrentMode</code> abgewartet bzw. überwacht werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-21a1446b56b1fdf2", "to": "FIG-0f7da0b9b6fec343", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
